commands.command:
/bin/zsh -lc python - <<'PY'
import subprocess
from itertools import product
from decimal import Decimal,localcontext
from fractions import Fraction
from more_itertools import numeric_range
ns={'__name__':'more_itertools.review_base','__package__':'more_itertools'}
exec(compile(subprocess.check_output(['git','show','10ac3e199dc9c85fe8952ac0d7bc961f0a9c8a51:more_itertools/more.py'],text=True),'base','exec'),ns)
Old=ns['numeric_range']
factories=[int,float,Fraction,Decimal]
triples=[tuple(fs[i](v) for i,v in enumerate(vals)) for fs in product(factories,repeat=3) for vals in [(10,20,2),(20,10,-2)]]
triples += [(2**53+1,2**53+10,.1),(2**53+1,2**53+1,1.),(-(2**53+1),-(2**53+10),-.1),(10,20,.1),(Fraction(10),Fraction(20),.1),(0.,1.,5e-324)]
checks=0;issues=[];changes=[]
for prec in [2,28]:
 for trapping in [False,True]:
  for args in triples:
   for make in factories:
    for v in [9,10,12,19,20,21]:
     value=make(v)
     for meth in ['contains','index']:
      records=[]
      for cls in [Old,numeric_range]:
       with localcontext() as ctx:
        ctx.prec=prec
        if trapping:
         for sig in ctx.traps:ctx.traps[sig]=True
        try:r=cls(*args)
        except Exception as e:records.append(('ctor',type(e).__name__,()));continue
        ctx.clear_flags()
        try:result=(value in r) if meth=='contains' else r.index(value);kind='ok'
        except Exception as e:result=type(e).__name__;kind='err'
        flags=tuple(sorted(s.__name__ for s,v in ctx.flags.items() if v))
        records.append((kind,result,flags))
      if records[0][0]=='ok':
       checks+=1
       if records[1][0]!='ok' or records[0][2]!=records[1][2]:issues.append((prec,trapping,args,value,meth,records))
       elif records[0][1]!=records[1][1]:changes.append((args,value,meth,records))
print('baseline-success calls checked',checks,'new exception/flag differences',len(issues),'result differences',len(changes))
for issue in issues[:15]:print(issue)
for change in changes[:5]:print('result',change)
assert not issues
PY

