from more_itertools import numeric_range
from decimal import Decimal, localcontext
from fractions import Fraction
from datetime import datetime, timedelta
import subprocess
import more_itertools.more as module
namespace = vars(module).copy()
exec(subprocess.check_output(['git', 'show', 'HEAD:more_itertools/more.py']), namespace)
original = namespace['numeric_range']
cases = [(0., 1., .1), (-8.732, -13.532, -2.4), (4.51, 10.375, .255), (-69.37276490678778, -29.8339073344664, 4.942357196540172), (32.50227965239458, 9.003418351482358, -1.9582384417426848), (1e16, 1e16 + 8, 1.), (-1e16, -1e16 - 8, -1.), (2**53 + 1, 2**53 + 10, .5), (-1e308, 1e308, 1e308)]
for args in cases:
    r = numeric_range(*args)
    items = list(iter(r))
    assert len(r) == len(items), (args, len(r), len(items))
    for value in items:
        assert value in r and r.index(value) == items.index(value), (args, value)
    for value in [args[1], *[x + .125 for x in items]]:
        assert (value in r) == (value in items), (args, value)
print('Float boundaries, repeated values, mixed types and overflow: passed')
def observe(cls, args, query, traps):
    with localcontext() as ctx:
        ctx.prec = 3
        if traps:
            for signal in ctx.traps:
                ctx.traps[signal] = True
        ctx.clear_flags()
        r = cls(*args)
        result = []
        for operation in [lambda: query in r, lambda: r.index(query)]:
            try:
                result.append(operation())
            except Exception as exc:
                result.append(type(exc).__name__)
        return result, {x.__name__ for x, raised in ctx.flags.items() if raised}
for args in [(0, 1000, 1), (Decimal(0), Decimal(1000), Decimal(1)), (Decimal(0), 1000., Decimal(1)), (Fraction(0), Fraction(1000), Fraction(1))]:
    for query in [0, 1, 999, 1000, .5, 1., Decimal('1'), Decimal('0.5'), Fraction(1, 2), Decimal('Infinity')]:
        for traps in [False, True]:
            before, after = observe(original, args, query, traps), observe(numeric_range, args, query, traps)
            assert before == after, (args, query, traps, before, after)
print('Exact domains, cross-type queries and Decimal contexts: passed')
